//! The 72 melakartas — every parent scale — generated by rule.
//!
//! A melakarta is a seven-note scale: Sa, one Ri, one Ga, one Ma, Pa, one
//! Dha, one Ni, ascending. Six (Ri, Ga) pairs × two Mas × six (Dha, Ni)
//! pairs = 72, and their numbering is itself the rule:
//!
//! * numbers 1–36 take M1, 37–72 take M2;
//! * each run of 36 is six *chakras* of six; the chakra picks the (Ri, Ga)
//!   pair, in the order R1G1, R1G2, R1G3, R2G2, R2G3, R3G3;
//! * the position within the chakra picks the (Dha, Ni) pair, in the same
//!   order: D1N1, D1N2, D1N3, D2N2, D2N3, D3N3.
//!
//! So no table of swaras is stored: [`Melakarta::new`] computes them. The
//! names are data (the Katapayadi scheme hides each number in its name's
//! first two syllables, which is how the names were chosen, not something
//! this crate needs to decode).

use super::swara::Swara;

/// The six (lower, upper) pairs, in melakarta order: (Ri, Ga) for the
/// chakra, (Dha, Ni) for the position within it.
const RG: [(Swara, Swara); 6] = [
    (Swara::R1, Swara::G1),
    (Swara::R1, Swara::G2),
    (Swara::R1, Swara::G3),
    (Swara::R2, Swara::G2),
    (Swara::R2, Swara::G3),
    (Swara::R3, Swara::G3),
];
const DN: [(Swara, Swara); 6] = [
    (Swara::D1, Swara::N1),
    (Swara::D1, Swara::N2),
    (Swara::D1, Swara::N3),
    (Swara::D2, Swara::N2),
    (Swara::D2, Swara::N3),
    (Swara::D3, Swara::N3),
];

/// The chakra names, in order (each groups six melakartas).
pub const CHAKRAS: [&str; 12] = [
    "Indu", "Netra", "Agni", "Veda", "Bana", "Rutu", "Rishi", "Vasu", "Brahma", "Disi", "Rudra",
    "Aditya",
];

