/// One of the 72 melakartas, by number.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Melakarta(u8);

impl Melakarta {
    /// Melakarta `n` (1–72), or `None` outside that range.
    #[must_use]
    pub const fn new(n: u8) -> Option<Self> {
        if n >= 1 && n <= 72 {
            Some(Self(n))
        } else {
            None
        }
    }

    /// All 72, in order.
    pub fn all() -> impl Iterator<Item = Self> {
        (1..=72).map(Self)
    }

    /// Its number, 1–72.
    #[must_use]
    pub const fn number(self) -> u8 {
        self.0
    }

    /// Its name.
    #[must_use]
    pub const fn name(self) -> &'static str {
        NAMES[self.0 as usize - 1]
    }

    /// Find one by name, ignoring case.
    #[must_use]
    pub fn by_name(name: &str) -> Option<Self> {
        NAMES
            .iter()
            .position(|n| n.eq_ignore_ascii_case(name))
            .and_then(|i| u8::try_from(i + 1).ok())
            .map(Self)
    }

    /// Its chakra, 1–12.
    #[must_use]
    pub const fn chakra(self) -> u8 {
        (self.0 - 1) / 6 + 1
    }

    /// Its chakra's name.
    #[must_use]
    pub const fn chakra_name(self) -> &'static str {
        CHAKRAS[self.chakra() as usize - 1]
    }

    /// The seven swaras, ascending: S, Ri, Ga, Ma, P, Dha, Ni.
    #[must_use]
    pub const fn swaras(self) -> [Swara; 7] {
        let i = self.0 as usize - 1;
        let (r, g) = RG[(i / 6) % 6];
        let (d, n) = DN[i % 6];
        let m = if self.0 <= 36 { Swara::M1 } else { Swara::M2 };
        [Swara::S, r, g, m, Swara::P, d, n]
    }

    /// The scale as semitones above Sa.
    #[must_use]
    pub const fn semitones(self) -> [u8; 7] {
        let s = self.swaras();
        [
            s[0].semitone(),
            s[1].semitone(),
            s[2].semitone(),
            s[3].semitone(),
            s[4].semitone(),
            s[5].semitone(),
            s[6].semitone(),
        ]
    }

    /// The scale spelled in notation: `"S R1 G3 M1 P D1 N3"`.
    #[must_use]
    pub fn spelled(self) -> String {
        self.swaras().map(Swara::name).join(" ")
    }

    /// The melakarta with the other Ma: n ↔ n ± 36 (its *prati-* or
    /// *shuddha-madhyama* twin).
    #[must_use]
    pub const fn madhyama_twin(self) -> Self {
        if self.0 <= 36 {
            Self(self.0 + 36)
        } else {
            Self(self.0 - 36)
        }
    }

    /// Which melakarta has these seven semitones (S and P included), if
    /// any.
    #[must_use]
    pub fn from_semitones(set: [u8; 7]) -> Option<Self> {
        Self::all().find(|m| m.semitones() == set)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn m(n: u8) -> Melakarta {
        Melakarta::new(n).unwrap()
    }

    #[test]
    fn the_anchors_every_student_learns() {
        assert_eq!(m(1).spelled(), "S R1 G1 M1 P D1 N1");
        assert_eq!(m(1).name(), "Kanakangi");
        // The lesson scale.
        assert_eq!(m(15).semitones(), [0, 1, 4, 5, 7, 8, 11]);
        assert_eq!(m(15).name(), "Mayamalavagowla");
        // The Western modes hide in the system.
        assert_eq!(
            m(20).semitones(),
            [0, 2, 3, 5, 7, 8, 10],
            "Natabhairavi: natural minor"
        );
        assert_eq!(
            m(22).semitones(),
            [0, 2, 3, 5, 7, 9, 10],
            "Kharaharapriya: Dorian"
        );
        assert_eq!(
            m(28).semitones(),
            [0, 2, 4, 5, 7, 9, 10],
            "Harikambhoji: Mixolydian"
        );
        assert_eq!(
            m(29).semitones(),
            [0, 2, 4, 5, 7, 9, 11],
            "Shankarabharanam: major"
        );
        assert_eq!(
            m(65).semitones(),
            [0, 2, 4, 6, 7, 9, 11],
            "Mechakalyani: Lydian"
        );
        assert_eq!(
            m(8).semitones(),
            [0, 1, 3, 5, 7, 8, 10],
            "Hanumathodi: Phrygian"
        );
        assert_eq!(m(72).spelled(), "S R3 G3 M2 P D3 N3");
        assert_eq!(m(72).name(), "Rasikapriya");
    }

    #[test]
    fn structural_invariants_hold_for_all_72() {
        let mut seen = std::collections::HashSet::new();
        for mk in Melakarta::all() {
            let s = mk.semitones();
            assert_eq!((s[0], s[4]), (0, 7), "{}: S and P are fixed", mk.name());
            assert!(
                s.windows(2).all(|w| w[0] < w[1]),
                "{}: ascending, no shared position",
                mk.name()
            );
            let letters: Vec<u8> = mk.swaras().iter().map(|w| w.letter()).collect();
            assert_eq!(letters, [0, 1, 2, 3, 4, 5, 6], "one of each note");
            assert!(seen.insert(s), "{} duplicates a scale", mk.name());
            assert_eq!(Melakarta::from_semitones(s), Some(mk));
            assert_eq!(mk.madhyama_twin().madhyama_twin(), mk);
        }
        assert_eq!(seen.len(), 72);
        let names: std::collections::HashSet<_> = NAMES.iter().collect();
        assert_eq!(names.len(), 72, "names are unique");
    }

    #[test]
    fn chakras_group_by_six() {
        assert_eq!(m(1).chakra_name(), "Indu");
        assert_eq!(m(15).chakra(), 3);
        assert_eq!(m(15).chakra_name(), "Agni");
        assert_eq!(m(72).chakra_name(), "Aditya");
        // The madhyama twin keeps every swara but Ma.
        let (a, b) = (m(29).swaras(), m(65).swaras());
        assert_eq!(m(29).madhyama_twin(), m(65));
        assert_eq!((a[3], b[3]), (Swara::M1, Swara::M2));
        assert_eq!([a[1], a[2], a[5], a[6]], [b[1], b[2], b[5], b[6]]);
    }

    #[test]
    fn lookup_by_name() {
        assert_eq!(Melakarta::by_name("kharaharapriya"), Some(m(22)));
        assert_eq!(
            Melakarta::by_name("Bhairavi"),
            None,
            "a janya raga, not a mela"
        );
        assert_eq!(Melakarta::new(0), None);
        assert_eq!(Melakarta::new(73), None);
    }
}
